<script setup lang="ts">
import { onMounted, ref } from "vue";
import AppBreadcrumb from "@/components/AppBreadcrumb.vue";
import ConfirmDialog from "@/components/ConfirmDialog.vue";
import PageHeader from "@/components/PageHeader.vue";
import StatusBadge from "@/components/StatusBadge.vue";
import { createNavigation, listNavigations, setNavigationState, updateNavigation, type Navigation, type NavigationPayload } from "@/services/administracion";

const items = ref<Navigation[]>([]); const allItems = ref<Navigation[]>([]); const page = ref(1); const search = ref(""); const estado = ref("all"); const pagination = ref({ page: 1, pageSize: 10, total: 0, totalPages: 0 });
const loading = ref(false); const saving = ref(false); const error = ref(""); const success = ref(""); const showForm = ref(false); const editing = ref<Navigation | null>(null); const target = ref<Navigation | null>(null);
const form = ref({ codigoNavegacion: "", nombreNavegacion: "", tituloNavegacion: "", descripcionNavegacion: "", tipoNavegacion: "ITEM", enlaceNavegacion: "", claseNavegacion: "", ordenNavegacion: 0, idNavegacionPadre: "", esVisible: true });
const routes = ["/inicio", "/campus", "/edificios", "/elevadores", "/dispositivos", "/beneficiarios", "/solicitudes", "/tarjetas", "/monitoreo", "/administracion/usuarios", "/administracion/perfiles", "/administracion/permisos", "/administracion/navegaciones", "/administracion/configuracion", "/administracion/auditoria"];
const message = (e: unknown) => e instanceof Error ? e.message : "Ocurrió un error inesperado";
async function load() { loading.value = true; error.value = ""; try { const result = await listNavigations({ page: page.value, pageSize: 10, search: search.value, estado: estado.value }); items.value = result.items; pagination.value = result.pagination; } catch (e) { error.value = message(e); } finally { loading.value = false; } }
async function loadAll() { try { allItems.value = (await listNavigations({ page: 1, pageSize: 100, estado: "all" })).items; } catch (e) { error.value = message(e); } }
function edit(item: Navigation | null) { editing.value = item; form.value = { codigoNavegacion: item?.codigoNavegacion ?? "", nombreNavegacion: item?.nombreNavegacion ?? "", tituloNavegacion: item?.tituloNavegacion ?? "", descripcionNavegacion: item?.descripcionNavegacion ?? "", tipoNavegacion: item?.tipoNavegacion ?? "ITEM", enlaceNavegacion: item?.enlaceNavegacion ?? "", claseNavegacion: item?.claseNavegacion ?? "", ordenNavegacion: item?.ordenNavegacion ?? 0, idNavegacionPadre: item?.idNavegacionPadre ? String(item.idNavegacionPadre) : "", esVisible: item?.esVisible ?? true }; showForm.value = true; }
async function save() { saving.value = true; error.value = ""; try { const payload: NavigationPayload = { ...form.value, descripcionNavegacion: form.value.descripcionNavegacion || null, enlaceNavegacion: form.value.enlaceNavegacion || null, claseNavegacion: form.value.claseNavegacion || null, idNavegacionPadre: form.value.idNavegacionPadre ? Number(form.value.idNavegacionPadre) : null }; if (editing.value) await updateNavigation(editing.value.idNavegacion, payload); else await createNavigation(payload); showForm.value = false; success.value = "Opción de navegación guardada."; await Promise.all([load(), loadAll()]); } catch (e) { error.value = message(e); } finally { saving.value = false; } }
async function toggle() { const item = target.value; target.value = null; if (!item) return; try { await setNavigationState(item.idNavegacion, !item.estadoNavegacion); success.value = `Opción ${item.estadoNavegacion ? "desactivada" : "activada"}.`; await Promise.all([load(), loadAll()]); } catch (e) { error.value = message(e); } }
onMounted(() => { void Promise.all([load(), loadAll()]); });
</script>

<template>
  <AppBreadcrumb :items="[{ label: 'Administración' }, { label: 'Navegación' }]" />
  <PageHeader eyebrow="Administración" title="Navegación" description="Organice rutas del frontend y las opciones visibles en el menú por perfil." action-label="Nueva opción" @action="edit(null)" />
  <div v-if="success" class="bo-notice bo-notice-success" role="status">{{ success }}</div><div v-if="error" class="bo-state bo-state-error" role="alert">{{ error }} <button class="bo-link" @click="load">Reintentar</button></div>
  <section class="bo-card"><form class="bo-toolbar" @submit.prevent="page = 1; load()"><input v-model="search" placeholder="Buscar título, código o ruta..." aria-label="Buscar navegación" /><select v-model="estado" aria-label="Estado"><option value="all">Todos los estados</option><option value="active">Activas</option><option value="inactive">Inactivas</option></select><button class="bo-btn bo-btn-primary">Buscar</button></form><div v-if="loading" class="bo-state">Cargando opciones...</div><div v-else-if="!items.length" class="bo-state">No hay opciones de navegación.</div><div v-else class="bo-table-wrap"><table><thead><tr><th>Opción</th><th>Tipo</th><th>Ruta</th><th>Orden</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in items" :key="item.idNavegacion"><td><strong>{{ item.tituloNavegacion }}</strong><br /><small>{{ item.codigoNavegacion }} · {{ item.tituloPadre ? `En ${item.tituloPadre}` : 'Raíz' }}</small></td><td>{{ item.tipoNavegacion }}</td><td>{{ item.enlaceNavegacion || '—' }}</td><td>{{ item.ordenNavegacion }}</td><td><StatusBadge :active="item.estadoNavegacion" /></td><td><div class="bo-actions"><button class="bo-action" @click="edit(item)">Editar</button><button class="bo-action" :class="{ danger: item.estadoNavegacion }" @click="target = item">{{ item.estadoNavegacion ? 'Desactivar' : 'Activar' }}</button></div></td></tr></tbody></table></div><footer class="bo-pagination"><span>{{ pagination.total }} opciones · Página {{ pagination.page }} de {{ Math.max(pagination.totalPages, 1) }}</span><div><button class="bo-page-button" :disabled="page <= 1 || loading" @click="page--; load()">Anterior</button><button class="bo-page-button" :disabled="page >= pagination.totalPages || loading" @click="page++; load()">Siguiente</button></div></footer></section>
  <div v-if="showForm" class="bo-modal-backdrop" @click.self="showForm = false"><section class="bo-modal"><header><div><span class="bo-eyebrow">Administración</span><h2>{{ editing ? 'Editar opción' : 'Crear opción' }}</h2></div><button class="bo-close" type="button" @click="showForm = false">×</button></header><form class="bo-form" @submit.prevent="save"><div class="bo-form-grid"><label>Código *<input v-model="form.codigoNavegacion" maxlength="64" pattern="[A-Za-z0-9_-]+" required /></label><label>Nombre *<input v-model="form.nombreNavegacion" maxlength="128" required /></label><label>Título *<input v-model="form.tituloNavegacion" maxlength="128" required /></label><label>Tipo *<select v-model="form.tipoNavegacion"><option value="ITEM">Opción</option><option value="MENU">Menú</option><option value="GRUPO">Grupo</option></select></label><label>Ruta frontend<select v-model="form.enlaceNavegacion"><option value="">Sin ruta (contenedor)</option><option v-for="route in routes" :key="route" :value="route">{{ route }}</option></select></label><label>Opción padre<select v-model="form.idNavegacionPadre"><option value="">Sin padre</option><option v-for="parent in allItems.filter(x => x.estadoNavegacion && x.idNavegacion !== editing?.idNavegacion)" :key="parent.idNavegacion" :value="String(parent.idNavegacion)">{{ parent.tituloNavegacion }}</option></select></label><label>Orden *<input v-model.number="form.ordenNavegacion" type="number" min="-32768" max="32767" required /></label><label>Clase CSS<input v-model="form.claseNavegacion" maxlength="64" /></label><label class="bo-form-wide">Descripción<textarea v-model="form.descripcionNavegacion" maxlength="512" rows="2" /></label><label class="bo-check-label"><input v-model="form.esVisible" type="checkbox" /> Visible en menú</label></div><p class="bo-form-note">Solo se pueden asociar rutas existentes en el frontend. Los accesos a la API siguen sujetos al RBAC del servidor.</p><footer class="bo-form-actions"><button class="bo-btn" type="button" @click="showForm = false">Cancelar</button><button class="bo-btn bo-btn-primary" :disabled="saving">{{ saving ? 'Guardando...' : 'Guardar opción' }}</button></footer></form></section></div>
  <ConfirmDialog :open="Boolean(target)" title="Cambiar estado de navegación" :message="target ? `¿Desea ${target.estadoNavegacion ? 'desactivar' : 'activar'} ${target.tituloNavegacion}?` : ''" :confirm-label="target?.estadoNavegacion ? 'Desactivar' : 'Activar'" @confirm="toggle" @cancel="target = null" />
</template>
